<?php require 'includes/functions.php';$pageTitle='New Arrivals';$q=mb_substr(textval('q',true),0,100);$category=textval('category',true);$brand=number('brand',true);$sort=textval('sort',true);$where=' WHERE p.is_active=1';$args=[];if($q!==''){$where.=' AND (p.name LIKE ? OR b.name LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($category!==''){$where.=' AND c.name=?';$args[]=$category;}if($brand){$where.=' AND b.id=?';$args[]=$brand;}if(textval('stock',true)==='1')$where.=' AND p.stock>0 AND p.is_sold_out=0';$order=['price_asc'=>'p.price ASC','price_desc'=>'p.price DESC','name'=>'p.name ASC'][$sort]??'p.created_at DESC,p.id ASC';$count=(int)query('SELECT COUNT(*) FROM products p JOIN brands b ON b.id=p.brand_id JOIN categories c ON c.id=p.category_id'.$where,$args)->fetchColumn();$pages=max(1,(int)ceil($count/12));$page=min($pages,max(1,number('page',true)));$offset=($page-1)*12;$products=query(product_sql().$where.' ORDER BY '.$order.' LIMIT 12 OFFSET '.$offset,$args)->fetchAll();$brands=query('SELECT * FROM brands ORDER BY name')->fetchAll();$categories=query('SELECT * FROM categories ORDER BY id')->fetchAll();require 'includes/header.php';?>
<section class="page-head"><div class="container"><span class="eyebrow">FIND SOMETHING UNFORGETTABLE</span><h1>Our Collection</h1><p class="muted">New arrivals, lasting impressions.</p></div></section><section class="container section"><form class="catalog-search" action="<?=e(url('new-arrivals.php'))?>" method="get"><label for="search">Search the collection</label><div class="search-row"><input id="search" type="search" name="q" maxlength="100" value="<?=e($q)?>" placeholder="Try Afnan, Khamrah or 9 PM" list="suggestions"><datalist id="suggestions"><?php foreach(query('SELECT name FROM products WHERE is_active=1 ORDER BY name LIMIT 100')->fetchAll() as $n):?><option value="<?=e($n['name'])?>"><?php endforeach;?></datalist><button>Search</button></div><details class="filters" <?=($category||$brand||$sort||textval('stock',true))?'open':''?>><summary>Filters & sort</summary><div class="form-grid"><label>Category<select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option <?= $category===$c['name']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Brand<select name="brand"><option value="">All brands</option><?php foreach($brands as $b):?><option value="<?=$b['id']?>" <?=$brand===$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label>Sort by<select name="sort"><?php foreach([''=>'Newest','price_asc'=>'Price: low to high','price_desc'=>'Price: high to low','name'=>'Name'] as $k=>$v):?><option value="<?=$k?>" <?=$sort===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="stock" value="1" <?=textval('stock',true)==='1'?'checked':''?>> In stock only</label></div><div class="actions"><button>Apply filters</button><a href="<?=e(url('new-arrivals.php'))?>">Clear filters</a></div></details></form><div class="section-head"><p class="muted"><?=$count?> fragrances</p><span>Page <?=$page?> of <?=$pages?></span></div><div class="product-grid"><?php foreach($products as $p)product_card($p);?></div><?php if(!$products):?><div class="empty"><h2>No fragrances found</h2><p>Try a different name or clear your filters.</p></div><?php endif;?><nav class="pagination" aria-label="Catalogue pages"><?php for($i=1;$i<=$pages;$i++):$params=['q'=>$q,'category'=>$category,'brand'=>$brand,'sort'=>$sort,'stock'=>textval('stock',true),'page'=>$i];?><a class="button outline" <?=$i===$page?'aria-current="page"':''?> href="<?=e(url('new-arrivals.php?'.http_build_query($params)))?>"><?=$i?></a><?php endfor;?></nav></section><?php require 'includes/footer.php';?>
